import{_ as o,o as i,c as t,a2 as a}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"ADR-0004 — Architettura Live Preview (SPIKE-04)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-live-preview.md","filePath":"adr/0004-live-preview.md"}'),r={name:"adr/0004-live-preview.md"};function n(d,e,c,s,l,u){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0004-—-architettura-live-preview-spike-04" tabindex="-1">ADR-0004 — Architettura Live Preview (SPIKE-04) <a class="header-anchor" href="#adr-0004-—-architettura-live-preview-spike-04" aria-label="Permalink to &quot;ADR-0004 — Architettura Live Preview (SPIKE-04)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>superata (in parte) da <a href="./0049-editor-live-milkdown.html">ADR-0049</a> il 2026-11-12: Live è Milkdown e il CodeMirror Live Preview è rimosso; restano validi per Source e Reading i punti 6 e 7, e il ponte del punto 5 come interfaccia</td></tr><tr><td><strong>Data</strong></td><td>2026-10-24</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (Editor), §2.7</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>in parte: HTML grezzo ridotto a un sottoinsieme sanificato; PDF via pdf.js (vedi sotto)</td></tr></tbody></table><blockquote><p><strong>Superata in parte (2026-11-12, A-W9 di M16).</strong> Il disegno dei punti 1–4 non esiste più nel codice: <code>livePreview.ts</code>, <code>blockWidgets.ts</code>, <code>widgets.ts</code>, <code>callouts.ts</code> e il <code>Compartment</code> di modalità sono stati rimossi. <strong>Live è l&#39;editor WYSIWYG Milkdown</strong> (<a href="./0049-editor-live-milkdown.html">ADR-0049</a>); <strong>Source resta CodeMirror 6</strong>, ma come editor a modalità fissa (<code>editor/source/SourceEditor.tsx</code>), non più come la stessa vista di Live con un <code>Compartment</code>. Valgono ancora il punto 6 (tasti: in Source, <code>Prec.highest</code> che passa al registro dei comandi), il punto 7 (Reading) e, come interfaccia e non più come <code>Facet</code>, il punto 5 (<code>LivePreviewContext</code> in <code>editor/context.ts</code>, che <code>NoteView</code> passa all&#39;editor come prop). Il testo qui sotto è la decisione originale e resta come storico; l&#39;alternativa «editor ProseMirror/WYSIWYG» che scartava è quella che ADR-0049 adotta, con uno strato che conserva il sorgente a byte.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Live Preview è la modalità predefinita: il testo resta Markdown, ma la sintassi si nasconde ovunque il cursore non sia e compaiono widget (embed, math, mermaid, callout). Deve restare fluida su note da 1 MB e condividere con l&#39;indexer le stesse regole di riconoscimento (link, tag, task, block id), altrimenti editor e indice divergono.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong>Un solo documento CodeMirror 6.</strong> Live Preview, Source e Reading non sono tre editor: Source e Live sono la stessa <code>EditorView</code> con un <code>Compartment</code> (<code>modeC</code>) che cambia le estensioni; selezione e scroll sopravvivono al cambio. Reading è un componente separato (<code>reading/ReadingView</code>) alimentato dal testo corrente.</li><li><strong>Decorazioni, non trasformazioni.</strong> <code>editor/livePreview.ts</code> costruisce un <code>DecorationSet</code> puro (<code>buildInline(state, ranges)</code>) sull&#39;albero <code>@lezer/markdown</code> (strutture a blocchi) più uno scanner di righe OFM (wikilink, embed, tag, highlight, commenti, block id) che usa le stesse regole del parser Go. La funzione è testabile senza DOM; il <code>ViewPlugin</code> la invoca solo sui range visibili e ricostruisce quando cambiano documento, selezione o viewport.</li><li><strong>Sintassi sulla riga del cursore.</strong> Ogni decorazione &quot;nascondi&quot; ha un&#39;esenzione quando la selezione tocca il suo intervallo: il token riappare e si può editare.</li><li><strong>Widget a blocchi in uno <code>StateField</code></strong> (<code>editor/blockWidgets.ts</code>): frontmatter (nascosto, la vista è il pannello Properties), math <code>$$</code>, mermaid, callout ripiegabili. Un blocco mostra il sorgente quando la selezione è al suo interno. Le decorazioni a blocchi non possono venire da un <code>ViewPlugin</code>, da qui lo <code>StateField</code>.</li><li><strong>Ponte verso l&#39;applicazione:</strong> l&#39;editor non importa mai le API. <code>editor/context.ts</code> definisce <code>LivePreviewContext</code> (risoluzione link con cache, rendering embed/immagini/math/mermaid, apertura link) fornita tramite <code>Facet</code>. <code>NoteView</code> la implementa; quando una risoluzione asincrona termina emette l&#39;effetto <code>linkStatusChanged</code> e le decorazioni si ricalcolano (link risolti vs fantasma).</li><li><strong>Tasti:</strong> le scorciatoie dell&#39;app passano da <code>Prec.highest(keymap.of([{ any }]))</code> → <code>commandForEvent</code>, così hanno la precedenza sulla keymap predefinita di CodeMirror (che altrimenti legherebbe <code>Mod-i</code> a &quot;selectParentSyntax&quot; e <code>Mod-Enter</code> a &quot;insertBlankLine&quot;). Lo stesso registro comandi serve palette, menu e hotkey personalizzati.</li><li><strong>Reading view:</strong> <code>unified</code> (<code>remark-parse</code>, <code>remark-gfm</code>, <code>remark-math</code>) con plugin OFM proprio → <code>rehype-raw</code> → DOMPurify, poi <em>idratazione</em> post-sanificazione (KaTeX, Mermaid, embed). DOMPurify vieta gli stili inline (D-01), quindi KaTeX/Mermaid sono inseriti dopo la sanificazione, da codice nostro, a partire da testo già escapato.</li></ol><h2 id="deviazioni-dallo-spec" tabindex="-1">Deviazioni dallo spec <a class="header-anchor" href="#deviazioni-dallo-spec" aria-label="Permalink to &quot;Deviazioni dallo spec&quot;">​</a></h2><ul><li><strong>HTML grezzo nelle note:</strong> è renderizzato solo il sottoinsieme che DOMPurify lascia passare (niente <code>&lt;script&gt;</code>, <code>&lt;style&gt;</code>, attributi <code>style</code>, handler). Coerente con D-01 e con la CSP di ADR-0005.</li><li><strong>PDF:</strong> incorporati con pdf.js caricato lazy (non <code>&lt;embed&gt;</code>), perché <code>&lt;embed&gt;</code> non è affidabile nei webview e non rispetta <code>#page=</code> ovunque.</li><li><strong>Vault switcher:</strong> il roadmap lo elenca tra i comandi; è coperto da &quot;Chiudi vault&quot;, che riporta alla schermata iniziale con i vault recenti.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Editor ProseMirror/WYSIWYG:</strong> il documento non sarebbe più il file Markdown; round-trip lossy, diff e merge (M2) più difficili.</li><li><strong>Due viste sovrapposte (editor nascosto + preview):</strong> cursore e selezione sincronizzati a mano, scroll fragile.</li><li><strong>Widget per ogni inline:</strong> costoso su note grandi; si usano <code>Decoration.mark/replace</code> e widget solo dove serve contenuto nuovo (checkbox, bullet, embed, math, mermaid).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Ogni nuova sintassi OFM va aggiunta in tre punti con lo stesso comportamento: parser Go, estrattore TS (<code>@memobrain/markdown</code>) e scanner di Live Preview, coperti dalle fixture di <code>shared/conformance/markdown</code>.</li><li>Le prestazioni dipendono dal limitare il lavoro ai range visibili; <code>livePreview.test.ts</code> fissa il comportamento, la prova di digitazione su 1 MB è manuale (<code>docs/qa/parita-funzionale-m1.md</code>).</li></ul>',13)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
